  "loc.endsImMyWay": "Termina «Sono in viaggio» all’arrivo.",
  "loc.enterInternetConnectionsAddress": "Inserisci come server l’indirizzo della vostra connessione Internet (ad es. l’indirizzo MyFRITZ!). Di solito si configura tramite un comando SMS, seguendo le istruzioni del localizzatore.",
  "loc.enterShopAddressesUnder": "Inserisci gli indirizzi dei negozi in Liste → Modifica lista della spesa. Se un negozio ha più sedi, puoi aggiungere gli indirizzi di tutte le filiali. Quando qualcuno rimane in uno di questi luoghi per un po’, la spesa pianificata viene contrassegnata come completata.",
  "loc.familyDoesntSeeYou": "La tua famiglia ora non ti vede sulla mappa.",
  "loc.familyDoesntSeeYou#wg": "La tua casa condivisa ora non ti vede sulla mappa.",
  "loc.familyGetsMessageSees": "La tua famiglia riceverà una notifica e potrà vedere la tua posizione in tempo reale fino al tuo arrivo a casa. Vuoi continuare?",
  "loc.familyGetsMessageSees#wg": "La tua casa condivisa riceverà una notifica e potrà vedere la tua posizione in tempo reale fino al tuo arrivo a casa. Vuoi continuare?",
  "loc.familySeesLiveDuration": "La famiglia ti vede dal vivo sulla mappa – con una durata, finisce da sola.",
  "loc.familySeesLiveDuration#wg": "La casa condivisa ti vede dal vivo sulla mappa – con una durata, finisce da sola.",
  "loc.fields": "Campi: {felder}",
  "loc.fromPinn": "da pinn.",
  "loc.fromTraccar": "da «Traccar Client»",
  "loc.gettingLocation": "Rilevamento posizione …",
  "loc.gpsTracker": "🛰️ Localizzatore GPS",
  "loc.guide1": "Installa l’app <b>«Traccar Client»</b> (App Store o Google Play, gratuita).",
  "loc.guide2": "Nell’app, inserisci in <b>ID dispositivo</b> (Device identifier):",
  "loc.guide3": "Inserisci in <b>URL del server</b>:",
  "loc.guide4": "Precisione <b>Media</b>, distanza <b>50 m</b>. L’app invia solo quando ti muovi – da fermo niente. Se ci sono altri campi (intervallo, heartbeat), heartbeat disattivato o 0.",
  "loc.guide5": "Consenti l’accesso alla posizione: <b>Sempre</b> e <b>Posizione esatta</b> attiva.",
  "loc.guide6": "Attiva l’interruttore <b>Servizio / Tracking</b> e <b>lascialo sempre attivo</b> – fatto. Da ora controlli tutto in pinn.: «Invia in modo continuo» sì o no, «Invia una volta» e SOS. Finché «Invia in modo continuo» è disattivato, nessuno vede la tua posizione e pinn. non registra alcun percorso.",
  "loc.guideIntro": "Senza altre app, «📍 Condividi posizione» funziona direttamente in pinn. – ma solo finché pinn. è aperto. Perché la posizione arrivi anche con pinn. chiuso e schermo bloccato, l’app gratuita «Traccar Client» la invia direttamente a pinn. (non serve un server Traccar). Uguale per iPhone e Android.",
  "loc.h025013Watch5093": ", H02 5013, Watch 5093, Teltonika 5027. Questa porta deve essere inoltrata dalla FRITZ!Box al NAS, perché il tracker si collega dalla rete mobile.",
  "loc.haveGoodTripFamily": "Buon viaggio! La famiglia è stata informata.",
  "loc.haveGoodTripFamily#wg": "Buon viaggio! La casa condivisa è stata informata.",
  "loc.home": "· Casa",
  "loc.howLong": "Per quanto tempo?",
  "loc.idRandomLinksPhone": "L’ID è generato casualmente e collega il telefono a questa persona.",
  "loc.ifSomeoneArrivesLeaves": "Quando qualcuno arriva in un luogo o lo lascia, viene inviata una notifica push. «Casa» disattiva anche lo stato «Sono in viaggio».",
  "loc.ifTrackerHasSos": "Se il localizzatore dispone di un pulsante SOS, pinn. avvisa tutta la famiglia tramite notifica push entro un minuto dal momento in cui Traccar rileva l’allarme.",
  "loc.ifTrackerHasSos#wg": "Se il localizzatore dispone di un pulsante SOS, pinn. avvisa tutta la casa tramite notifica push entro un minuto dal momento in cui Traccar rileva l’allarme.",
  "loc.imeiTrackerPackagingComes": "Il codice IMEI si trova sul tracker o sulla confezione, oppure può essere ottenuto tramite un comando SMS.",
