  "loc.setup": "Configurazione · {famDeviceName}",
  "loc.setupIntro": "Gli smartphone non hanno bisogno d’altro: ognuno può condividere direttamente in pinn. sotto «La mia posizione». In background (pinn. chiuso) lo smartphone invia con l’app gratuita «Traccar Client» (iPhone e Android) – direttamente a pinn., non serve un server Traccar. Solo i tracker GPS con SIM (p. es. al collare) hanno bisogno del container «traccar». Le posizioni restano sul vostro NAS.",
