  "loc.shareIntro": "La tua famiglia ti vede dal vivo sulla mappa. Si invia solo quando ti muovi – da fermo niente. Con pinn. chiuso invia l’app «Traccar Client» configurata una volta.",
  "loc.shareIntro#wg": "La tua casa condivisa ti vede dal vivo sulla mappa. Si invia solo quando ti muovi – da fermo niente. Con pinn. chiuso invia l’app «Traccar Client» configurata una volta.",
