  "loc.testSameProcessReal": "Test: stessa procedura di una vera richiesta di aiuto (notifica push, finestra popup, mappa, indirizzo), ma solo per te: la famiglia non riceverà alcuna notifica.",
  "loc.testSameProcessReal#wg": "Test: stessa procedura di una vera richiesta di aiuto (notifica push, finestra popup, mappa, indirizzo), ma solo per te: la casa condivisa non riceverà alcuna notifica.",
  "loc.tipSetAddressUnder": "Suggerimento: imposta il tuo indirizzo in Impostazioni → Casa. Verrà creato automaticamente il luogo «Casa» e riceverai notifiche push quando arrivi o te ne vai.",
  "loc.traccarClientChooseSend": "In «Traccar Client», seleziona «Invia SOS» (a seconda della versione, dall’app oppure tenendo premuta l’icona dell’app). pinn. avvisa subito tutti i membri della famiglia con una notifica push che include posizione, indirizzo, ora e pulsanti per chiamare o contattare i soccorsi {regionNotrufText}. Suggerimento: inserisci il tuo numero di cellulare nella scheda di emergenza.",
  "loc.traccarClientChooseSend#wg": "In «Traccar Client», seleziona «Invia SOS» (a seconda della versione, dall’app oppure tenendo premuta l’icona dell’app). pinn. avvisa subito tutti i coinquilini con una notifica push che include posizione, indirizzo, ora e pulsanti per chiamare o contattare i soccorsi {regionNotrufText}. Suggerimento: inserisci il tuo numero di cellulare nella scheda di emergenza.",
