  "settings.calendar.fromFamily#wg": "dalla casa condivisa · pinn.",
  "settings.calendar.info": "Ogni profilo accede con il proprio account iCloud o Google e seleziona i calendari da utilizzare. «Per me» mostra solo i calendari del proprio profilo; «Famiglia» è visibile e utilizzabile da tutti i membri della famiglia. Gli altri vedono soltanto quale account fornisce un calendario familiare, con l’indirizzo oscurato (ad es. m**l@g***l.com). Gli eventi si possono creare, modificare e spostare come di consueto, anche offline; vengono salvati direttamente su iCloud o Google e quindi sul telefono. La sincronizzazione avviene ogni 15 minuti oppure selezionando «Sincronizza ora». È possibile usare anche un calendario sul solo server pinn., senza collegare un account. Promemoria e riepilogo giornaliero arrivano tramite notifica push; gli eventi privati vengono notificati soltanto a te.",
  "settings.calendar.info#wg": "Ogni profilo accede con il proprio account iCloud o Google e seleziona i calendari da utilizzare. «Per me» mostra solo i calendari del proprio profilo; «Casa condivisa» è visibile e utilizzabile da tutti i coinquilini. Gli altri vedono soltanto quale account fornisce un calendario della casa, con l’indirizzo oscurato (ad es. m**l@g***l.com). Gli eventi si possono creare, modificare e spostare come di consueto, anche offline; vengono salvati direttamente su iCloud o Google e quindi sul telefono. La sincronizzazione avviene ogni 15 minuti oppure selezionando «Sincronizza ora». È possibile usare anche un calendario sul solo server pinn., senza collegare un account. Promemoria e riepilogo giornaliero arrivano tramite notifica push; gli eventi privati vengono notificati soltanto a te.",
