  "settings.home.confirmRemove": "Vuoi rimuovere questa casa? Meteo, orari del sole e centro della mappa saranno disponibili solo dopo aver inserito un nuovo indirizzo. La posizione «Casa» nella condivisione della posizione rimarrà invariata.",
