  "settings.home.info": "La casa è condivisa da tutta la famiglia: nel calendario vengono mostrati meteo, festività e vacanze scolastiche della vostra regione; sono disponibili anche alba e tramonto (ad esempio nella pagina dei bambini) e la posizione di casa, con notifiche push all’arrivo e alla partenza. La mappa si apre su questa posizione. pinn. non chiederà più la posizione a ogni avvio. La ricerca degli indirizzi viene eseguita dal vostro server.",
