  "settings.shopping.info": "Negozio abituale: qui vengono aggiunti gli ingredienti del piano dei pasti, manualmente, tramite sincronizzazione o direttamente. Liste speciali: gli ingredienti con determinate parole chiave (ad es. carne macinata, fettine, pancetta) vengono inseriti in un’altra lista, per esempio quella della macelleria. L’impostazione vale per tutti i dispositivi della famiglia.",
  "settings.shopping.info#wg": "Negozio abituale: qui vengono aggiunti gli ingredienti del piano dei pasti, manualmente, tramite sincronizzazione o direttamente. Liste speciali: gli ingredienti con determinate parole chiave (ad es. carne macinata, fettine, pancetta) vengono inseriti in un’altra lista, per esempio quella della macelleria. L’impostazione vale per tutti i dispositivi della casa condivisa.",
