  "smart.guide1": "1. Crea un nuovo comando rapido chiamato «pinn Automatik»:",
  "smart.guide10": "Il dispositivo deve poter raggiungere pinn. (tramite il Wi-Fi di casa o una VPN). Ogni azione viene eseguita una sola volta per attività; se è già stata avviata manualmente con il pulsante, l’automazione non la avvierà di nuovo.",
