  "smart.guide8": "2. Nella scheda «Automazione», scegli «Ora del giorno». Crea un’automazione per ogni orario indicato in alto e seleziona «Esegui immediatamente» → «pinn Automatik».",
  "smart.guide9": "3. Suggerimento: aggiungi anche «Arrivo» (Casa) → «Automazione pinn.» per recuperare automaticamente le azioni saltate.",
  "smart.haAddress": "Indirizzo",
  "smart.haAddressHint": "Inserisci semplicemente l’indirizzo IP che usi nel browser. pinn. proverà automaticamente http://, https:// e la porta 8123. «homeassistant.local» non funziona in questo caso: usa l’indirizzo IP (Home Assistant → Impostazioni → Sistema → Rete, oppure controlla il router).",
