  "smart.haDevices": "Dispositivi tramite Home Assistant: {list}",
  "smart.haIntro": "Il server pinn. controlla direttamente Home Assistant: i pulsanti funzionano su qualsiasi dispositivo, anche Android, e le automazioni, compresa l’opzione «Quando si spunta», funzionano senza Comandi Rapidi. Con un’entità di stato, pinn. attende che il dispositivo, ad esempio il robot aspirapolvere, abbia terminato.",
  "smart.haNeedAddress": "Inserisci l’indirizzo.",
  "smart.haNoDevices": "Non ci sono ancora dispositivi tramite Home Assistant. Nella scheda «Dispositivi», aggiungi un dispositivo e seleziona «Home Assistant».",
