  "smart.haOff": "Home Assistant non connesso",
  "smart.haOn": "Home Assistant connesso",
  "smart.haSearching": "Ricerca di Home Assistant…",
  "smart.haTip1": "Roborock: crea un dispositivo «Robot aspirapolvere» e seleziona in alto il robot (vacuum.…): pinn. caricherà le stanze dalla mappa. Per ogni azione scegli «Pulizia stanza», le stanze e la modalità (aspirazione, aspirazione e lavaggio, solo lavaggio). «Stanza dell’attività» usa la stanza associata alla pulizia domestica: i nomi devono corrispondere a quelli dell’app Roborock.",
  "smart.haTip2": "Il robot funge anche da indicatore di stato: l’azione successiva parte solo quando il robot è tornato alla stazione.",
  "smart.haTip3": "Gli script ricevono il nome della stanza nella variabile <span class=\"font-mono\">raum</span>: così un solo script gestisce tutte le stanze.",
  "smart.haTip4": "Luci/LED: imposta il colore e la luminosità direttamente nell’azione.",
  "smart.haTip5": "L’automazione viene eseguita sul server ogni minuto: non serve configurare nulla sul telefono.",
  "smart.haToken": "Token di accesso a lunga durata",
  "smart.haTokenHint": "In Home Assistant, apri il tuo profilo in basso a sinistra → scheda «Sicurezza» → «Token di accesso a lunga durata» → «Crea token» e incolla l’intera stringa. Non è necessario anteporre «Bearer»: pinn. lo aggiunge automaticamente (ma non è un problema se lo fai). Il token rimane sul server e non viene mai inviato ai dispositivi.",
